    to: finalEndTime,
    channelCount: 1,
    sampleRate: Self.writerSampleRate,
    input: input
  )
  guard filled > 0 else { return }

  recordGapFill(for: track, filled: filled)
  recordTailPadding(for: track, filled: filled, seconds: tailSeconds)
  Log.info(
    Log.recorder, "recorder",
    "\(track.rawValue): padded tail with \(filled) silence buffers to common end")
}

